codeExample:
.btn {
  display: inline-block;
  padding: 10px 16px;
  background: #0f8a8a;
  color: white;
  border: none;
  border-radius: 8px;
  text-decoration: none;
}

.btn:hover { background: #0c6e6e; }
.btn:focus { outline: 3px solid #b8f000; outline-offset: 2px; }

label.check {
  display: flex;
  gap: 8px;
  align-items: center;
}

label.check input {
  width: 18px;
  height: 18px;
  accent-color: #0f8a8a;
}
